$scriptPath=Join-Path $PSScriptRoot 'Invoke-Exp024HpTouchpoint.ps1'
Describe 'EXP-024 engineering contract' {
  BeforeAll {$text=Get-Content -LiteralPath $scriptPath -Raw}
  It 'parses as PowerShell' {$tokens=$null;$errors=$null;[void][System.Management.Automation.Language.Parser]::ParseFile($scriptPath,[ref]$tokens,[ref]$errors);@($errors).Count|Should -Be 0}
  It 'uses ShouldProcess and strict candidate identity' {$text|Should -Match 'SupportsShouldProcess';$text|Should -Match 'HPTouchpointAnalyticsService';$text|Should -Match 'Service display identity refused';$text|Should -Match 'Service executable identity refused'}
  It 'requires elevation and refuses pending reboot or enterprise management' {foreach($t in 'Elevation required','Pending reboot detected','Enterprise-managed domain state refused','Enterprise MDM enrollment refused','Enterprise ConfigMgr ownership refused'){$text|Should -Match ([regex]::Escape($t))}}
  It 'enforces the HP security version floor and publisher identity' {$text|Should -Match '4\.2\.2439\.0';$text|Should -Match 'Get-AuthenticodeSignature';$text|Should -Match 'HP publisher signature refused';$text|Should -Match 'Outdated HP Touchpoint Analytics version refused'}
  It 'captures exact binary startup dependency running boot and protected state' {foreach($name in 'registryStart','delayedAutoStart','executableVersion','executableHash','signatureSubject','dependencies','dependents','serviceAccount','capturedBootTime','capturedUtc','protected','management'){$text|Should -Match $name}}
  It 'implements the full explicit reversible lifecycle' {foreach($name in 'Check','Capture','DryRun','Apply','Verify','VerifyReboot','Rollback'){$text|Should -Match "'$name'"}}
  It 'provides structured JSONL logging idempotence and failure retention' {foreach($t in 'schemaVersion=3','ConvertTo-Json -Compress','userSid','already-applied',"'failure' 'failure'",'ErrorActionPreference'){$text|Should -Match ([regex]::Escape($t))}}
  It 'makes WhatIf paths mutation free after state capture' {$text|Should -Match '\$WhatIfPreference';$text|Should -Match "'apply' 'whatif'";$text|Should -Match "'rollback' 'whatif'";$text|Should -Match "'apply-declined'";$text|Should -Match "'rollback-declined'"}
  It 'requires a later boot for reboot persistence' {$text|Should -Match 'capturedBootTime';$text|Should -Match 'A later boot is required for reboot persistence verification';$text|Should -Match 'Reboot persistence failed'}
  It 'preserves exact registry existence type and data during rollback' {$text|Should -Match 'GetValueKind';$text|Should -Match 'RegistryValueKind';$text|Should -Match 'Restore-RegistryValue';$text|Should -Match 'Remove-ItemProperty';$text|Should -Match 'Exact rollback verification failed';$text|Should -Match 'restoredExactOriginal'}
  It 'preserves running state during application and exact rollback' {$text|Should -Match 'preserving current running state';$text|Should -Match 'runningStatePreserved';$text|Should -Match 'Start-Service';$text|Should -Match 'Stop-Service'}
  It 'holds Windows Update security and protected remote access state' {foreach($name in 'WinDefend','mpssvc','wuauserv','UsoSvc','BITS','Tailscale','TermService','Windows Update dependency disabled','Rollback protected state changed'){$text|Should -Match ([regex]::Escape($name))}}
  It 'avoids package device driver firmware and broad service mutation' {$text|Should -Not -Match 'Remove-AppxPackage|Uninstall-Package|Remove-PnpDevice|Disable-PnpDevice|pnputil.+delete-driver|Remove-Item.+DriverStore|bcdedit|sc\.exe\s+delete'}
  It 'retains physical evidence and avoids Stable promotion' {$text|Should -Match 'needs-evidence';$text|Should -Not -Match 'status:stable|Stable='}
}
